def limpar_citacoes(texto):
    """Tira as marcas internas de citação da busca (ex.: 【2†L6-L10】)."""
    texto = re.sub(r"【[^】]*】", "", texto or "")
    return re.sub(r"[ \t]+\n", "\n", texto).strip()


@st.cache_data(ttl=6 * 60 * 60, show_spinner=False, max_entries=300)
def _pesquisa_cache(pergunta, dia, chave, sistema_extra=""):
    """Faz a pesquisa na internet (guarda por 6 h para não repetir a mesma busca)."""
    sistema = sistema_extra.replace("{dia}", dia) if sistema_extra else (
        f"Hoje é {dia}. Você é consultor de marketing para pequenos negócios brasileiros e explica "
        "de forma simples, para leigos. Use a busca na internet para trazer informações ATUAIS. "
        "Responda em português do Brasil, organizado em tópicos curtos e práticos. Diga a data ou "
        "o período dos dados quando houver. No final, liste as fontes com o link de cada uma em "
        "uma seção 'Fontes:'. Não invente números: se não encontrar, diga que não encontrou. "
        "Na PRIMEIRA linha da resposta, escreva a confiança geral, exatamente num destes "
        "formatos: 'Confiança: 🟢 alta — várias fontes confiáveis concordam', 'Confiança: 🟡 "
        "média — poucas fontes ou fontes que discordam' ou 'Confiança: 🔴 baixa — não encontrei "
        "informação confiável'. Só use 🟢 com pelo menos 2 fontes independentes concordando.")
    ultimo = ""
    for modelo in MODELOS_BUSCA:
        try:
            r = requests.post(
                f"{GROQ_BASE}/chat/completions",
                headers={"Authorization": f"Bearer {chave}", "Content-Type": "application/json"},
                json={"model": modelo, "messages": [{"role": "system", "content": sistema},
                                                    {"role": "user", "content": pergunta}],
                      "tools": [{"type": "browser_search"}], "tool_choice": "required",
                      "reasoning_effort": "low", "max_completion_tokens": 3000,
                      "temperature": 0.6},
                timeout=150)
        except requests.RequestException as e:
            ultimo = str(e)
            continue
        if r.status_code == 200:
            texto = r.json()["choices"][0]["message"].get("content") or ""
            if texto.strip():
                return limpar_citacoes(texto), True
        ultimo = erro_api(r)
    raise RuntimeError(ultimo or "a pesquisa não respondeu")


def pesquisa_ao_vivo(pergunta, sistema_extra="", chave=None):
    """Pesquisa atualizada na internet. Se não der, responde sem busca e avisa.
    Devolve (texto, ao_vivo)."""
    dia = time.strftime("%d/%m/%Y")
    try:
        return _pesquisa_cache(pergunta, dia, chave or st.session_state.groq_key, sistema_extra)
    except Exception as e:
        aviso = str(e)
    if sistema_extra:  # pesquisas com instrução própria: sem busca real, não responde
        raise RuntimeError("A pesquisa na internet não está disponível agora, e sem ela o "
                           "raio-X não seria confiável. Tente de novo em alguns minutos. "
                           f"(Detalhe: {aviso[:160]})")
    texto = chat_groq([
        {"role": "system", "content": "Você é consultor de marketing para pequenos negócios "
         "brasileiros. Responda em português do Brasil, em tópicos curtos e práticos, para leigos. "
         "Deixe claro que é conhecimento geral, sem dados de hoje."},
        {"role": "user", "content": pergunta}], temperatura=0.6)
    return texto + f"\n\n_(Pesquisa ao vivo indisponível agora: {aviso[:160]})_", False


def analisar_anuncio(texto, negocio):
    return chat_groq([
        {"role": "system", "content":
         "Você é especialista em anúncios de vídeo curto (TikTok, Reels, Shorts) para pequenos "
         "negócios no Brasil. Analise o roteiro do anúncio e responda em português do Brasil, "
         "assim:\n"
         "**Nota geral: X/10**\n"
         "Depois, uma tabela em markdown com as colunas Critério | Nota (0-10) | Comentário, "
         "avaliando: Gancho dos 3 primeiros segundos; Clareza da mensagem; Oferta / benefício; "
         "Chamada para ação; Prova ou confiança; Cara de rede social (não de comercial de TV); "
         "Tamanho ideal.\n"
         "Depois: **3 melhorias principais** (bem práticas) e **Versão melhorada do gancho** "
         "(3 opções de primeira frase). Seja honesto e direto, em linguagem simples."},
        {"role": "user", "content": f"Negócio: {negocio or '-'}\nRoteiro do anúncio:\n{texto}"}],
        temperatura=0.4)


def contar_fontes(texto):
    """Quantos links e sites diferentes a resposta usou como fonte."""
    from urllib.parse import urlparse
    urls = set(u.rstrip(".,;:") for u in re.findall(r"https?://[^\s\)\]>\"'】]+", texto or ""))
    sites = set()
    for u in urls:
        try:
            sites.add(urlparse(u).netloc.lower().removeprefix("www."))
        except Exception:
            pass
    return len(urls), len({x for x in sites if x})


def painel_confianca(texto):
    """Mostra quantas fontes foram usadas e a confiança de cada seção; avisa se há poucas fontes."""
    n_links, n_sites = contar_fontes(texto)
    verdes, amarelos, vermelhos = (len(re.findall(r"Confian[çc]a:\s*" + c, texto or ""))
                                   for c in ("🟢", "🟡", "🔴"))
    partes = [f"📚 **{n_sites} site(s) diferentes** consultados ({n_links} links)"]
    if verdes + amarelos + vermelhos:
        partes.append(f"Confiança: 🟢 {verdes} · 🟡 {amarelos} · 🔴 {vermelhos}")
    st.markdown(" &nbsp;|&nbsp; ".join(partes))
    if n_sites < 3:
        st.warning(f"⚠️ **Poucas fontes encontradas ({n_sites}).** Trate este resultado com "
                   "cuidado e confira nos links antes de decidir. Tente também escrever o nome "
                   "do produto ou do negócio de outro jeito (marca, modelo, cidade).")
    elif vermelhos and vermelhos >= max(verdes, 1):
        st.warning("⚠️ Várias partes ficaram com **confiança baixa** (🔴): a internet tem pouca "
                   "informação confiável sobre isso. Confira as fontes antes de decidir.")
    st.caption("🟢 alta — várias fontes concordam · 🟡 média — poucas fontes ou divergentes · "
               "🔴 baixa — não encontrou informação confiável")


