def app():
    hero("Vídeos de publicidade grátis e ponte para vídeos ultra profissionais com inteligência artificial.")
    c1, c2 = st.columns([5, 1], vertical_alignment="center")
    c1.markdown(f"👋 Olá, **{st.session_state.nome}**!")
    if c2.button("Sair", key="sair"):
        for k in list(st.session_state.keys()):
            del st.session_state[k]
        st.rerun()
    abas = st.tabs(["🎁 Criar vídeo grátis", "💎 Criar vídeos ultra profissionais", "📁 Meus vídeos",
                    "📈 Aprenda a anunciar", "🤖 Assistente IA", "📚 Tutorial"])
    with abas[0]:
        aba_gratis()
    with abas[1]:
        aba_pago()
    with abas[2]:
        aba_galeria()
    with abas[3]:
        aba_aprenda()
    with abas[4]:
        aba_assistente()
    with abas[5]:
        aba_tutorial()


